mapper.update:
UPDATE engine_session SET resume_version = #{resumeVersion},
                          resume_path = #{resumePath},
                          updated_at = #{updatedAt}
WHERE id = #{id} AND worker_id = #{workerId} AND owner_epoch = #{ownerEpoch}
  AND lease_until > UTC_TIMESTAMP(6)

UPDATE engine_session
SET lease_until = DATE_ADD(UTC_TIMESTAMP(6), INTERVAL #{leaseSeconds} SECOND),
    updated_at  = UTC_TIMESTAMP(6)
WHERE resource_id = #{resourceId}
  AND engine_type = #{engineType}
  AND worker_id   = #{workerId}
  AND owner_epoch = #{ownerEpoch}
  AND lease_until > UTC_TIMESTAMP(6)
  AND state NOT IN ('STOPPED', 'FAILED')
